/**
 * 分立器件检测手布（2 层）：
 * 左：二极管/LED 竖直支路；右上 NPN+NMOS；右下 PNP+TO-220。
 * VCC 顶总线；GND 靠 B 铺铜；驱动网 BASE/GATE 等走 F 走廊 + B 下降列到排针。
 */
function handLayoutLabDiscrete(doc) {
  doc.tracks = [];
  doc.vias = [];
  doc.zones = [];
  doc.footprints = doc.footprints.filter(f => !!f.schematicCompId);

  // IRF540 必须 TO-220（勿留 SOT-23）
  {
    const fp = doc.footprints.find(f => f.refDes === 'M2');
    if (fp && fp.defId !== 'FP_TO2203') {
      const neu = instantiate('FP_TO2203', 'M2', fp.value || 'IRF540', fp.position, 0, fp.schematicCompId);
      fp.defId = neu.defId;
      fp.pads = neu.pads;
      for (const pad of fp.pads) { pad.netId = undefined; pad.netName = undefined; }
    }
  }

  const byRef = new Map(doc.footprints.map(f => [f.refDes, f]));
  const setPos = (ref, x, y, rot = 0) => {
    const fp = byRef.get(ref);
    if (!fp) return;
    fp.position = { x, y };
    fp.rotation = rot;
    fp.mirrored = false;
    fp.layer = 'F.Cu';
  };
  const netByName = (name) => doc.nets.find(n => (n.name || '').toUpperCase() === name);
  const gnd = doc.nets.find(n => isGndNet(n.name));
  const vcc = netByName('VCC');
  const base = netByName('BASE');
  const coll = netByName('COLL');
  const collLed = netByName('COLL_LED');
  const baseP = netByName('BASE_P');
  const collP = netByName('COLL_P');
  const gate = netByName('GATE');
  const drain = netByName('DRAIN');
  const drainLed = netByName('DRAIN_LED');
  const gate2 = netByName('GATE2');
  const drain2 = netByName('DRAIN2');
  const dio = [0, 1, 2].map(i => netByName(`DIO${i}`));
  const ledn = [0, 1, 2].map(i => netByName(`LED${i}`));

  const bindPad = (ref, num, net) => {
    const fp = byRef.get(ref);
    const pad = fp?.pads.find(p => p.number === String(num));
    if (!pad || !net) return;
    pad.netId = net.id;
    pad.netName = net.name;
  };
  // 强制脚位：BJT 1=B 2=C 3=E；MOS/TO220 1=G 2=D 3=S
  bindPad('Q1', 1, base); bindPad('Q1', 2, collLed); bindPad('Q1', 3, gnd);
  bindPad('Q2', 1, baseP); bindPad('Q2', 2, collP); bindPad('Q2', 3, vcc);
  bindPad('M1', 1, gate); bindPad('M1', 2, drainLed); bindPad('M1', 3, gnd);
  bindPad('M2', 1, gate2); bindPad('M2', 2, drain2); bindPad('M2', 3, gnd);

  // —— 布局：二极管/LED 三列；右侧有源 ——
  for (let i = 0; i < 3; i++) {
    const x = 220 + i * 180;
    setPos(`RD${i + 1}`, x, 200, 90);
    setPos(`D${i + 1}`, x, 360, 90);
    setPos(`RL${i + 1}`, x, 560, 90);
    setPos(`LED${i + 1}`, x, 720, 90);
  }
  // NPN + 集电极 LED
  setPos('RB1', 820, 220, 0);
  setPos('Q1', 1000, 220, 0);
  setPos('RC1', 1000, 100, 0);
  setPos('DN', 1180, 100, 0);
  // NMOS + 漏极 LED
  setPos('RG1', 1400, 220, 0);
  setPos('M1', 1580, 220, 0);
  setPos('RM1', 1580, 100, 0);
  setPos('DM', 1760, 100, 0);
  // PNP
  setPos('RB2', 820, 900, 0);
  setPos('Q2', 1000, 900, 0);
  setPos('RC2', 1180, 900, 0);
  // IRF540：RM2 放下方，漏极下出，避免与栅极扇出争道
  setPos('RG2', 1400, 900, 0);
  setPos('M2', 1620, 980, 0);
  setPos('RM2', 1860, 1140, 0);

  // 仅引出电源；驱动网在板内本地短连，避免长扇出互穿
  const hdr = instantiate('FP_PINHDR_4', 'J1', '1x4', { x: 2000, y: 480 }, 0);
  const hdrNets = [gnd, vcc, gnd, vcc];
  for (let i = 0; i < hdr.pads.length; i++) {
    const n = hdrNets[i];
    if (!n) continue;
    hdr.pads[i].netId = n.id;
    hdr.pads[i].netName = n.name;
  }
  doc.footprints.push(hdr);
  byRef.set('J1', hdr);

  const pw = (ref, num) => {
    const fp = byRef.get(ref) || doc.footprints.find(f => f.refDes === ref);
    const pad = fp?.pads.find(p => p.number === String(num));
    return pad ? padWorld(fp, pad) : null;
  };
  const add = (net, a, b, w = 14, layer = 'F.Cu') => {
    if (!net || !a || !b || dist(a, b) < 0.5) return;
    doc.tracks.push({
      id: uid('trk'), layer,
      start: { x: a.x, y: a.y }, end: { x: b.x, y: b.y },
      width: w, netId: net.id, netName: net.name
    });
  };
  const addVia = (net, p) => {
    if (!net || !p) return;
    for (const v of doc.vias) {
      if (v.netId === net.id && Math.abs(v.position.x - p.x) < 0.5 &&
        Math.abs(v.position.y - p.y) < 0.5) return;
    }
    doc.vias.push({
      id: uid('via'), position: { x: p.x, y: p.y },
      drill: 12, diameter: 24,
      netId: net.id, netName: net.name,
      layers: ['F.Cu', 'B.Cu'], kind: 'through'
    });
  };
  const L = (net, pts, w = 14, layer = 'F.Cu') => {
    for (let i = 0; i < pts.length - 1; i++) add(net, pts[i], pts[i + 1], w, layer);
  };

  // 二极管/LED 支路短连
  for (let i = 0; i < 3; i++) {
    add(dio[i], pw(`RD${i + 1}`, 2), pw(`D${i + 1}`, 1), 12, 'F.Cu');
    add(ledn[i], pw(`RL${i + 1}`, 2), pw(`LED${i + 1}`, 1), 12, 'F.Cu');
    const dk = pw(`D${i + 1}`, 2);
    const lk = pw(`LED${i + 1}`, 2);
    if (gnd && dk) addVia(gnd, dk);
    if (gnd && lk) addVia(gnd, lk);
  }

  // VCC：顶/中 F 总线；底部单独 F 母线，经左脊 B 上升到顶（不占右侧扇出通道）
  const vBusTop = 40;
  const vBusMid = 480;
  const vBusBot = 1280;
  const vSpineX = 100;
  if (vcc) {
    add(vcc, { x: vSpineX, y: vBusTop }, { x: 1700, y: vBusTop }, 20, 'F.Cu');
    add(vcc, { x: vSpineX, y: vBusMid }, { x: 700, y: vBusMid }, 20, 'F.Cu');
    add(vcc, { x: vSpineX, y: vBusTop }, { x: vSpineX, y: vBusMid }, 20, 'F.Cu');
    for (let i = 1; i <= 3; i++) {
      const p = pw(`RD${i}`, 1);
      if (p) add(vcc, { x: p.x, y: vBusTop }, p, 16, 'F.Cu');
      const q = pw(`RL${i}`, 1);
      if (q) add(vcc, { x: q.x, y: vBusMid }, q, 16, 'F.Cu');
    }
    for (const ref of ['RB1', 'RC1', 'RG1', 'RM1']) {
      const p = pw(ref, 1);
      if (p) add(vcc, { x: p.x, y: vBusTop }, p, 16, 'F.Cu');
    }
    // 底母线只接到 Q2.E；RM2 经右侧下探到母线以东再左接到脊（避开 DRAIN2）
    const q2e = pw('Q2', 3);
    const rm2a = pw('RM2', 1);
    if (q2e) {
      add(vcc, { x: vSpineX, y: vBusBot }, { x: q2e.x + 40, y: vBusBot }, 16, 'F.Cu');
      add(vcc, q2e, { x: q2e.x, y: vBusBot }, 16, 'F.Cu');
      addVia(vcc, { x: vSpineX, y: vBusBot });
      add(vcc, { x: vSpineX, y: vBusBot }, { x: vSpineX, y: vBusMid }, 16, 'B.Cu');
      addVia(vcc, { x: vSpineX, y: vBusMid });
    }
    if (rm2a) {
      // RM2.VCC：右侧短逃后走 B 回左脊，避开 F 上的 DRAIN2
      const esc = { x: rm2a.x + 50, y: rm2a.y };
      add(vcc, rm2a, esc, 16, 'F.Cu');
      addVia(vcc, esc);
      add(vcc, esc, { x: vSpineX, y: vBusBot }, 16, 'B.Cu');
    }
  }

  // NPN 网络
  add(base, pw('RB1', 2), pw('Q1', 1), 12, 'F.Cu');
  add(coll, pw('RC1', 2), pw('DN', 1), 12, 'F.Cu');
  add(collLed, pw('DN', 2), pw('Q1', 2), 12, 'F.Cu');
  if (gnd) addVia(gnd, pw('Q1', 3));

  // NMOS
  add(gate, pw('RG1', 2), pw('M1', 1), 12, 'F.Cu');
  add(drain, pw('RM1', 2), pw('DM', 1), 12, 'F.Cu');
  add(drainLed, pw('DM', 2), pw('M1', 2), 12, 'F.Cu');
  if (gnd) addVia(gnd, pw('M1', 3));

  // PNP
  add(baseP, pw('RB2', 2), pw('Q2', 1), 12, 'F.Cu');
  add(collP, pw('Q2', 2), pw('RC2', 1), 12, 'F.Cu');
  if (gnd) {
    addVia(gnd, pw('RB2', 1));
    addVia(gnd, pw('RC2', 2));
  }

  // M2：栅极下拉；漏极下探后从下方接入 RM2.2，避免横穿 RM2.1(VCC)
  add(gate2, pw('RG2', 2), pw('M2', 1), 12, 'F.Cu');
  {
    const d = pw('M2', 2);
    const r = pw('RM2', 2);
    if (d && r) {
      const under = r.y + 55;
      L(drain2, [d, { x: d.x, y: under }, { x: r.x, y: under }, r], 14, 'F.Cu');
    }
  }
  if (gnd) {
    addVia(gnd, pw('RG2', 1));
    addVia(gnd, pw('M2', 3));
  }

  const jGnd = pw('J1', 1);
  const jVcc = pw('J1', 2);
  const jGnd2 = pw('J1', 3);
  const jVcc2 = pw('J1', 4);
  // 侧向接入排针，禁止竖线穿过其它排针焊盘
  if (vcc && jVcc) {
    const col = jVcc.x - 70;
    L(vcc, [
      { x: 1700, y: vBusTop },
      { x: col, y: vBusTop },
      { x: col, y: jVcc.y },
      jVcc
    ], 20, 'F.Cu');
    if (jVcc2) L(vcc, [jVcc, { x: col, y: jVcc.y }, { x: col, y: jVcc2.y }, jVcc2], 20, 'F.Cu');
  }
  if (gnd && jGnd) addVia(gnd, jGnd);
  if (gnd && jGnd2) addVia(gnd, jGnd2);

  const named = [vcc, gnd, base, baseP, gate, gate2, coll, collLed, collP, drain, drainLed, drain2, ...dio, ...ledn];
  return {
    trackCount: doc.tracks.length,
    netCount: named.filter(Boolean).length,
    viaCount: doc.vias.length
  };
}

