/**
 * 分立器件检测手布（2 层）：
 * 左：二极管/LED 竖直支路；右上 NPN+NMOS；右下 PNP+TO-220。
 * 电源：顶/中 F 总线 + 右缘竖脊供下半区；信号全部本地正交短连。
 */
function handLayoutLabDiscrete(doc) {
  doc.tracks = [];
  doc.vias = [];
  doc.zones = [];
  doc.footprints = doc.footprints.filter(f => !!f.schematicCompId);

  {
    const fp = doc.footprints.find(f => f.refDes === 'M2');
    if (fp && fp.defId !== 'FP_TO2203') {
      const neu = instantiate('FP_TO2203', 'M2', fp.value || 'IRF540', fp.position, 0, fp.schematicCompId);
      fp.defId = neu.defId;
      fp.pads = neu.pads;
      for (const pad of fp.pads) { pad.netId = undefined; pad.netName = undefined; }
    }
  }

  const byRef = new Map(doc.footprints.map(f => [f.refDes, f]));
  const setPos = (ref, x, y, rot = 0) => {
    const fp = byRef.get(ref);
    if (!fp) return;
    fp.position = { x, y };
    fp.rotation = rot;
    fp.mirrored = false;
    fp.layer = 'F.Cu';
  };
  const netByName = (name) => doc.nets.find(n => (n.name || '').toUpperCase() === name);
  const gnd = doc.nets.find(n => isGndNet(n.name));
  const vcc = netByName('VCC');
  const base = netByName('BASE');
  const coll = netByName('COLL');
  const collLed = netByName('COLL_LED');
  const baseP = netByName('BASE_P');
  const collP = netByName('COLL_P');
  const gate = netByName('GATE');
  const drain = netByName('DRAIN');
  const drainLed = netByName('DRAIN_LED');
  const gate2 = netByName('GATE2');
  const drain2 = netByName('DRAIN2');
  const dio = [0, 1, 2].map(i => netByName(`DIO${i}`));
  const ledn = [0, 1, 2].map(i => netByName(`LED${i}`));

  const bindPad = (ref, num, net) => {
    const fp = byRef.get(ref);
    const pad = fp?.pads.find(p => p.number === String(num));
    if (!pad || !net) return;
    pad.netId = net.id;
    pad.netName = net.name;
  };
  bindPad('Q1', 1, base); bindPad('Q1', 2, collLed); bindPad('Q1', 3, gnd);
  bindPad('Q2', 1, baseP); bindPad('Q2', 2, collP); bindPad('Q2', 3, vcc);
  bindPad('M1', 1, gate); bindPad('M1', 2, drainLed); bindPad('M1', 3, gnd);
  bindPad('M2', 1, gate2); bindPad('M2', 2, drain2); bindPad('M2', 3, gnd);

  // —— 布局（同行焊盘对齐，便于正交短连）——
  // SOT23：pad1/2 在封装上方 y-45 相对… padWorld: pad1=(-35,45)→世界 cy+45
  for (let i = 0; i < 3; i++) {
    const x = 200 + i * 160;
    setPos(`RD${i + 1}`, x, 180, 90);
    setPos(`D${i + 1}`, x, 340, 90);
    setPos(`RL${i + 1}`, x, 520, 90);
    setPos(`LED${i + 1}`, x, 680, 90);
  }
  // NPN：电阻与三极管 B/C 焊盘同高；集电极 LED 在上方同行
  setPos('Q1', 920, 220, 0);       // B/C @ y=265
  setPos('RB1', 760, 265, 0);
  setPos('RC1', 920, 100, 0);
  setPos('DN', 1100, 100, 0);
  // NMOS 同理
  setPos('M1', 1480, 220, 0);
  setPos('RG1', 1320, 265, 0);
  setPos('RM1', 1480, 100, 0);
  setPos('DM', 1660, 100, 0);
  // PNP：E 在封装下方；VCC 下轨对准 E
  setPos('Q2', 920, 900, 0);       // E @ y=855, B/C @ y=945
  setPos('RB2', 760, 945, 0);
  setPos('RC2', 1100, 945, 0);
  // TO-220：D 在上方；RM2 放在漏极正上方，直连
  setPos('M2', 1520, 980, 0);      // D @ y=1070
  setPos('RG2', 1320, 980, 0);
  setPos('RM2', 1520, 820, 0);     // 在 M2 上方，与 D 同 x

  const hdr = instantiate('FP_PINHDR_4', 'J1', '1x4', { x: 1920, y: 480 }, 0);
  // 上两脚 GND，下两脚 VCC，便于识别
  const hdrNets = [gnd, gnd, vcc, vcc];
  for (let i = 0; i < hdr.pads.length; i++) {
    const n = hdrNets[i];
    if (!n) continue;
    hdr.pads[i].netId = n.id;
    hdr.pads[i].netName = n.name;
  }
  doc.footprints.push(hdr);
  byRef.set('J1', hdr);

  const pw = (ref, num) => {
    const fp = byRef.get(ref) || doc.footprints.find(f => f.refDes === ref);
    const pad = fp?.pads.find(p => p.number === String(num));
    return pad ? padWorld(fp, pad) : null;
  };
  const add = (net, a, b, w = 14, layer = 'F.Cu') => {
    if (!net || !a || !b || dist(a, b) < 0.5) return;
    doc.tracks.push({
      id: uid('trk'), layer,
      start: { x: a.x, y: a.y }, end: { x: b.x, y: b.y },
      width: w, netId: net.id, netName: net.name
    });
  };
  const addVia = (net, p) => {
    if (!net || !p) return;
    for (const v of doc.vias) {
      if (v.netId === net.id && Math.abs(v.position.x - p.x) < 0.5 &&
        Math.abs(v.position.y - p.y) < 0.5) return;
    }
    doc.vias.push({
      id: uid('via'), position: { x: p.x, y: p.y },
      drill: 12, diameter: 24,
      netId: net.id, netName: net.name,
      layers: ['F.Cu', 'B.Cu'], kind: 'through'
    });
  };
  const L = (net, pts, w = 14, layer = 'F.Cu') => {
    for (let i = 0; i < pts.length - 1; i++) add(net, pts[i], pts[i + 1], w, layer);
  };
  /** 正交折线（先竖后横，或先横后竖） */
  const ortho = (net, a, b, w = 12, preferVertFirst = false) => {
    if (!net || !a || !b) return;
    if (Math.abs(a.x - b.x) < 0.5 || Math.abs(a.y - b.y) < 0.5) {
      add(net, a, b, w, 'F.Cu');
      return;
    }
    if (preferVertFirst) L(net, [a, { x: a.x, y: b.y }, b], w, 'F.Cu');
    else L(net, [a, { x: b.x, y: a.y }, b], w, 'F.Cu');
  };

  // 二极管 / LED 竖直支路
  for (let i = 0; i < 3; i++) {
    add(dio[i], pw(`RD${i + 1}`, 2), pw(`D${i + 1}`, 1), 12, 'F.Cu');
    add(ledn[i], pw(`RL${i + 1}`, 2), pw(`LED${i + 1}`, 1), 12, 'F.Cu');
    if (gnd) {
      addVia(gnd, pw(`D${i + 1}`, 2));
      addVia(gnd, pw(`LED${i + 1}`, 2));
    }
  }

  // VCC：顶总线（二极管+上半有源）、中总线（LED 限流）、下总线（PNP.E + RM2）经右脊与顶连通
  const vBusTop = 40;
  const vBusMid = 440;
  const vBusLow = 780;
  const vSpineL = 80;
  const vSpineR = 1800;
  if (vcc) {
    add(vcc, { x: vSpineL, y: vBusTop }, { x: vSpineR, y: vBusTop }, 20, 'F.Cu');
    add(vcc, { x: vSpineL, y: vBusMid }, { x: 700, y: vBusMid }, 18, 'F.Cu');
    add(vcc, { x: vSpineL, y: vBusTop }, { x: vSpineL, y: vBusMid }, 18, 'F.Cu');
    // 下半电源轨 + 右脊上升到顶
    add(vcc, { x: 700, y: vBusLow }, { x: vSpineR, y: vBusLow }, 18, 'F.Cu');
    add(vcc, { x: vSpineR, y: vBusLow }, { x: vSpineR, y: vBusTop }, 18, 'F.Cu');

    for (let i = 1; i <= 3; i++) {
      const p = pw(`RD${i}`, 1);
      if (p) add(vcc, { x: p.x, y: vBusTop }, p, 14, 'F.Cu');
      const q = pw(`RL${i}`, 1);
      if (q) add(vcc, { x: q.x, y: vBusMid }, q, 14, 'F.Cu');
    }
    for (const ref of ['RB1', 'RC1', 'RG1', 'RM1']) {
      const p = pw(ref, 1);
      if (p) add(vcc, { x: p.x, y: vBusTop }, p, 14, 'F.Cu');
    }
    // Q2.E、RM2.1 → 下轨短接
    const q2e = pw('Q2', 3);
    const rm2a = pw('RM2', 1);
    if (q2e) add(vcc, q2e, { x: q2e.x, y: vBusLow }, 14, 'F.Cu');
    if (rm2a) add(vcc, rm2a, { x: rm2a.x, y: vBusLow }, 14, 'F.Cu');
